// value noise 1D/2D/3D with quintic fade, range [-1, 1]
function vnoise1(x, seed = 0) { const i = Math.floor(x), f = x - i; const u = f * f * f * (f * (f * 6 - 15) + 10); return lerp(hash2(i, seed), hash2(i + 1, seed), u) * 2 - 1; }
