          if (Number.isFinite(npc.y) && Math.abs(npc.y - (p[1] - (S.leg || 0))) > 1.75) continue;
          const dx2 = p[0] - npc.x, dz2 = p[2] - npc.z, dist2 = Math.hypot(dx2, dz2), minD = 0.62 + (npc.radius || 0.45);
