    const dz = T[2] - H[2], dy = T[1] - H[1], Dd = Math.hypot(dz, dy), Dc = clamp(Dd, Math.abs(A - L.l2) + 0.03 * L.L, A + L.l2 - 0.004 * L.L), base = Math.atan2(dy, dz);
