    const toeF = Math.hypot(S.TOEF[1], S.TOEF[2]), toeH = Math.hypot(S.TOEH[1], S.TOEH[2]), taF = Math.atan2(S.TOEF[1], S.TOEF[2]), taH = Math.atan2(S.TOEH[1], S.TOEH[2]);
