    const n = AVF.normal(x, z, 0.8), fx = Math.sin(a.yaw), fz = -Math.cos(a.yaw), nf = (n[0] * fx + n[2] * fz) * a.tilt, nr = (-n[0] * fz + n[2] * fx) * a.tilt * 0.35;
