        if (d < 70) AVF.kick(t, w0, [f[0] * a.v * (fore ? 0.35 : -0.2), 0.5, f[2] * a.v * (fore ? 0.35 : -0.2)], (fore ? 0.4 : 0.7) * (0.7 + 0.8 * (c.powder || 0.3)));
        if (d < 22) Sound.event({ type: 'hoof', d: d * 1.5, side: sign((w0[0] - S.p[0]) * S.r[0] + (w0[2] - S.p[2]) * S.r[2]) || 1, k: fore ? 0.2 : 0.3 });
