    // line, across and down the hill to the trees on its own side
    const vT = a.st === 0 ? W.v : a.st === 3 ? T.v : a.st === 4 ? (still ? 8 : clamp(vs * 0.42, 7.5, 10.5)) : 0;
    a.v += clamp((vT - a.v) * (a.st === 4 ? 4 : 5), a.st === 4 ? -14 : -3.5, a.st === 4 ? 13 : 2.5) * dt;
