    c[i] = p[0] - o[0]; c[i + 1] = p[1] - o[1]; c[i + 2] = p[2] - o[2]; c[i + 3] = t0; c[i + 4] = v[0]; c[i + 5] = v[1]; c[i + 6] = v[2]; c[i + 7] = rnd();
