    if (S.air) airEnd = t;
    if (!S.contact || sp < 1.2) { P.intensity = damp(P.intensity, 0, 12, H); P.face = faceEnv(t); return; }
    const g = 9.81, N = S.load / g, lat = Math.abs(S.aReac) / g, skid = Math.abs(Math.sin(S.beta));
