    let id = 0;
    for (const L of D.layers) { gfx.draw(pipe, { u: { p: [L.W, L.power, L.fall, id], o: [o[0], o[1], o[2], 0], w: ow }, tex: { tDepth: R.depth, tShadow: R.shadowTex }, count: 4, instances: Math.ceil(L.n * Quality.L.dust) }); id += L.n; }
