    const treeFS = out => TREE_FS.replace('GHOST_OUT', out).replace('V0F', V0.toFixed(2)).replace('DVF', (V1 - V0).toFixed(2));
    pipe = gfx.pipeline(Object.assign({ name: 'tree', vs: treeVS(false), fs: treeFS('o.color = vec4f(col, 1.0);') }, treeDesc));
