      name: 'treeBake', lib: [SL.common, SL.hash, TREE_SURF_SSL, TREE_MAT_SSL], buffers: [mesh], varyings: { nrm: 'vec3f', bp: 'vec3f', mat: 'vec4f', tx: 'vec4f', cl: 'vec4f' }, uniforms: { a: 'vec4f', r: 'vec4f', m: 'vec4f' },
