  let fresh: vec3f = mix(vec3f(0.112, 0.082, 0.060), vec3f(0.145, 0.094, 0.060), tR); let aged: vec3f = mix(vec3f(0.122, 0.118, 0.112), vec3f(0.168, 0.165, 0.158), tG); let dark: vec3f = vec3f(0.056, 0.044, 0.035);
