  let isLobby: f32 = step(0.50, hs);
  let lgt: vec3f = U.sunCol.rgb * (saturate(dot(N, L)) * sh) + townAmb(N);
  let dWarm: vec3f = mix(vec3f(1.0, 0.64, 0.30), vec3f(1.0, 0.80, 0.52), fract(hs * 4.3));
  let dRv: vec3f = reflect(-V, N); let dFr: f32 = 0.08 + 0.92 * pow(1.0 - saturate(dot(N, V)), 4.5);
