    let dLeaf: f32 = (1.0 - smoothstep(0.88, 0.90, du)) * smoothstep(0.03, 0.06, hg) * (1.0 - smoothstep(2.36, 2.38, hg));
    let dGlass: f32 = dLeaf * smoothstep(0.035, 0.055, du) * (1.0 - smoothstep(0.80, 0.82, du)) * smoothstep(0.24, 0.27, hg) * (1.0 - smoothstep(2.26, 2.29, hg));
    let dBar: f32 = dLeaf * (1.0 - smoothstep(0.025, 0.035, abs(hg - 1.02)));
    let dHandle: f32 = dLeaf * (1.0 - smoothstep(0.02, 0.03, abs(du - 0.11))) * smoothstep(0.86, 0.88, hg) * (1.0 - smoothstep(1.38, 1.40, hg));
