    let ex: vec2f = (cb.xy / cb.w - ca.xy / ca.w) * hr; let ey: vec2f = (ch.xy / ch.w - cl.xy / cl.w) * hr;
    let lx: f32 = max(length(ex), 1e-3); let ly: f32 = max(length(ey), 1e-3);
    let ox: f32 = (cx * 2.0 - 1.0) * 0.75; let oy: f32 = (cy * 2.0 - 1.0) * 0.75;
