  v.st = vec4f(s, t, a.i1.z, a.i1.w); v.ab = a.i0; v.py = vec4f(a.i2.x, a.i2.y, a.i1.x, a.i1.y);
  v.ca = a.i3; v.cb = a.i4; v.mi = vec4f(a.i2.z, a.i2.w, a.i5.x, a.i5.y); v.ex = vec4f(a.i5.z, 0.0, 0.0, 0.0);
