  let amt: f32 = b * gain * smoothstep(a.i2.w + 0.004, a.i2.w - 0.004, e) * feet.x * (1.0 - feet.y) * exp(-dist / 15000.0) * step(dist - 45.0, cityZ(cityUV(d))) * M.q.x * M.p.z;
