    if (sd <= rag) { R = floorAt(lowest(g, sphi, cphi, lift, sl * hw, sm) - D, (q.x * dl.y - q.y * dl.x) / ll, lump.z, skid, pw); }
    o.color = vec4f(M.e.x + R * M.e.y, 0.6 * v.e.x, M.e.x + R * M.e.y, 1.0);
