const AVZ_BGM = (() => {
  const LIST = [
    { id: 'glacier', n: '冰川微光' },
    { id: 'pine',    n: '松林晚风' },
    { id: 'starlit', n: '星野夜航' },
    { id: 'off',     n: '关闭' }
  ];
  const B = { id: 0, list: LIST, prevUntil: 0, _inst: null };
  try {
    const saved = localStorage.getItem('avz-bgm');
    const idx = LIST.findIndex(q => q.id === saved);
    if (idx >= 0) B.id = idx;
    else localStorage.setItem('avz-bgm', LIST[0].id);
  } catch (e) {}

  const nowMs = () => (typeof performance !== 'undefined' ? performance.now() : Date.now());
  B.currentId = () => LIST[B.id] ? LIST[B.id].id : 'glacier';
  B.set = (i, preview) => {
    B.id = ((i % LIST.length) + LIST.length) % LIST.length;
    const item = LIST[B.id];
    try { localStorage.setItem('avz-bgm', item.id); } catch (e) {}
    if (item.id === 'off') {
      B.prevUntil = 0;
    } else if (preview) {
      B.prevUntil = nowMs() + 16000;
      try {
        if (typeof Sound !== 'undefined') {
          if (Sound.unlock) Sound.unlock();
          if (Sound.on && Sound.rig && Sound.ctx) Sound.rig.fade(Sound.level || 0.8, Sound.ctx.currentTime, 0.18);
        }
      } catch (e) {}
    } else {
      B.prevUntil = 0;
    }
    if (B._inst && B._inst.onSelect) B._inst.onSelect(item.id, !!preview);
    return item;
  };
  B.hush = () => { B.prevUntil = 0; };
  B._dbg = () => ({
    playing: B._inst ? B._inst.isPlaying() : false,
    id: B.currentId(),
    index: B.id,
    state: B._inst && B._inst.ctx ? B._inst.ctx.state : 'none',
    score: B._inst && B._inst.dbg ? B._inst.dbg() : null
  });
  try { window.__avzBgm = B; } catch (e) {}
  return B;
})();

