        const norm = 0.58 / pk, attN = Math.round(sr * 0.0042), relN = Math.round(sr * 0.08);
        for (let i = 0; i < len; i++) {
          out[i] *= norm * (i < attN ? 0.5 * (1 - Math.cos(Math.PI * i / attN)) : 1) * (i > len - relN ? (len - i) / relN : 1);
        }
