      const p = T.wantP < T.tierP && T.dwP < 2 ? T.tierP : T.wantP;
      const b = T.wantB < T.tierB && T.dwB < 2 ? T.tierB : T.wantB;
      if (p !== T.tierP) { T.dwP = 0; say(t, 'pulse ' + p); }
      if (b !== T.tierB) { T.dwB = 0; say(t, 'bass ' + b); }
      T.tierP = p; T.tierB = b;
      set(h.arp, [0, 0.74, 0.90, 1][p] * T.kind.a, t, p ? 0.3 : 0.6);
      set(h.bas, [0.46, 0.82, 1.0][b], t, 0.35);
