        T.pos = T.next = T.abs = T.step = T.bar = T.chord = 0;
        T.wantP = T.wantB = T.tierP = T.tierB = T.carve = T.bloom = T.hush = T.fly = 0;
        T.ph = null; T.ansPh = null;
        T.set = T.want; T.sp = effSpeed; h.out.v = NaN;
